package util

import (
	"os"
	"path/filepath"
	"testing"
)

func TestIsGeneratedContent(t *testing.T) {
	cases := map[string]bool{
		GeneratedHeader + "\n\npackage models\n":        true,
		RustGeneratedHeader + "\n":                      true,
		"// Auto-generated by buildtool-model. x\n":     true,
		"// Auto-generated TypeScript types for User\n": true,
		"\ufeff" + GeneratedHeader + "\r\n":             true,
		"package models\n":                              false,
		"// mine\n" + GeneratedHeader + "\n":            false,
		"":                                              false,
	}
	for content, want := range cases {
		if got := IsGeneratedContent(content); got != want {
			t.Errorf("IsGeneratedContent(%q) = %v, want %v", content, got, want)
		}
	}
}

// 머리줄 없는 기존 파일은 덮어쓰지 않고, 생성 파일 / 없는 파일은 쓴다. Force 면 덮어쓴다.
func TestWriteGenerated(t *testing.T) {
	dir := t.TempDir()
	user := filepath.Join(dir, "models", "db.go")
	os.MkdirAll(filepath.Dir(user), 0755)
	os.WriteFile(user, []byte("package models\n// mine\n"), 0644)
	gen := GeneratedHeader + "\n\npackage models\n"

	if written, err := WriteGenerated(user, gen); err != nil || written {
		t.Fatalf("user file: written=%v err=%v", written, err)
	}
	if b, _ := os.ReadFile(user); string(b) != "package models\n// mine\n" {
		t.Fatalf("user file overwritten: %q", b)
	}
	if !SkippedUserFile(user) {
		t.Error("SkippedUserFile(user) = false")
	}

	fresh := filepath.Join(dir, "new", "dir", "user.go")
	if written, err := WriteGenerated(fresh, gen); err != nil || !written {
		t.Fatalf("new file: written=%v err=%v", written, err)
	}
	if written, _ := WriteGenerated(fresh, gen+"// v2\n"); !written {
		t.Error("generated file not rewritten")
	}
	if written, _ := WriteGenerated(fresh, gen+"// v2\n"); written {
		t.Error("unchanged content rewritten")
	}

	Force = true
	defer func() { Force = false }()
	if written, _ := WriteGenerated(user, gen); !written {
		t.Error("Force did not overwrite user file")
	}
}
